use std::collections::HashMap;

fn two_sum(nums: Vec<i32>, target: i32) -> Option<(usize, usize)> {
    let mut map: HashMap<i32, Vec<usize>> = HashMap::new();
    // Build a map from value to all its indices
    for (i, &v) in nums.iter().enumerate() {
        map.entry(v).or_default().push(i);
    }
    // Sort each index list so we can binary‐search for the smallest j > i
    for indices in map.values_mut() {
        indices.sort_unstable();
    }

    let n = nums.len();
    for i in 0..n {
        let a = nums[i];
        // compute the needed complement, skipping if subtraction would overflow
        if let Some(b) = target.checked_sub(a) {
            if let Some(indices) = map.get(&b) {
                let key = i + 1;
                // find the first index >= key, which ensures j > i
                match indices.binary_search(&key) {
                    Ok(pos) | Err(pos) if pos < indices.len() => {
                        return Some((i, indices[pos]));
                    }
                    _ => {}
                }
            }
        }
    }

    None
}

